'use strict';
window.sustainScene=function(stage){const k='<p class="edits-kicker">ROBUSTNESS × SUSTAINABILITY · IEEE TSUSC</p>';
 if(stage===0)return k+`<div class="edit-options"><button data-distribution="0" aria-pressed="true">IID clients</button><button data-distribution="1" aria-pressed="false">Non-IID clients</button></div><div class="federated-hub">Shared model ↔ local adversarial training</div><div class="client-grid">${Array.from({length:9},(_,i)=>`<div>Client ${i+1}<span>▰ ▰ ▰</span></div>`).join('')}</div><p class="edits-note" id="distribution-caption">Conceptual view: clients have similarly distributed data. The study compares controlled single-device and heterogeneous multi-device setups.</p>${paperFigure('fal-overview.png','View the study framework')}`;
 if(stage===1)return k+`<div class="edit-options"><button data-cost="0" aria-pressed="true">Carbon · RCTI</button><button data-cost="1" aria-pressed="false">Energy · RETI</button><button data-cost="2" aria-pressed="false">Latency · RTTI</button></div><div class="adapt-result" id="cost-formula"><strong>RCTI = ΔC / ΔR</strong><p>Relative change in carbon emissions per relative change in adversarial robustness.</p></div><p class="edits-note">Changes are measured relative to the first-round baseline. Robustness uses accuracy under adversarial evaluation. A ratio alone does not identify a universally best system.</p>`;
 return k+`<div class="edit-options"><button data-lens="0" aria-pressed="true">Resource costs</button><button data-lens="1" aria-pressed="false">Robustness tradeoff</button></div><div id="tradeoff-lens" class="adapt-result"><strong>Read energy, emissions and latency together</strong><p>Client count, data distribution and device capability affect the observed resource profile.</p></div><p class="edits-note">FGSM experiments use MNIST, CIFAR-10 and TinyImageNet, not deployed CPS. Read raw costs alongside indices, especially when the robustness change is near zero.</p>${paperFigure('fal-client-results.png','View reported client-scaling results')}`;};
window.bindSustainScene=function(stage,scene,pause){function bind(attr,fn){scene.querySelectorAll('['+attr+']').forEach(b=>b.addEventListener('click',()=>{pause();scene.querySelectorAll('['+attr+']').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));fn(Number(b.getAttribute(attr)))}))}
 bind('data-distribution',i=>{scene.querySelector('.client-grid').classList.toggle('heterogeneous',!!i);scene.querySelector('#distribution-caption').textContent=i?'Conceptual view: client data distributions differ. Resource and robustness effects must be measured, not inferred from these illustrative colors.':'Conceptual view: clients have similarly distributed data. The study compares controlled single-device and heterogeneous multi-device setups.'});
 bind('data-cost',i=>{const names=['Carbon emissions','Energy consumption','Latency'],symbols=['C','E','T'],codes=['RCTI','RETI','RTTI'];scene.querySelector('#cost-formula').innerHTML=`<strong>${codes[i]} = Δ${symbols[i]} / ΔR</strong><p>Relative change in ${names[i].toLowerCase()} per relative change in adversarial robustness.</p>`});
 bind('data-lens',i=>{scene.querySelector('#tradeoff-lens').innerHTML=i?'<strong>Robustness gains also have a cost</strong><p>Compare adversarial accuracy with resource changes; interpret both the numerator and denominator.</p>':'<strong>Read energy, emissions and latency together</strong><p>Client count, data distribution and device capability affect the observed resource profile.</p>'});scene.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)pause()}));};
